package pzvrphysicality;
import java.lang.reflect.*;import se.krka.kahlua.j2se.J2SEPlatform;import se.krka.kahlua.vm.KahluaTable;import viewpoint.core.Frame;import viewpointvr.physics.PackedModelGeometry;import zombie.inventory.*;import zombie.iso.*;

/** Production native-item producer/facade with a separately controlled provider, using the retained authored SDK matrix. */
public final class NativeStorageProviderTest {
 private static int checks;private static void check(boolean value,String why){if(!value)throw new AssertionError(why);checks++;}
 private static Object field(String name)throws Exception{var f=NativeStorage.class.getDeclaredField(name);f.setAccessible(true);return f.get(null);}
 private static Frame frame(){var f=new Frame();f.camX=12000.5f;f.camY=9000.5f;f.camZ=.4f;return f;}
 public static void main(String[] args)throws Exception{
  check(NativeStorage.class.getProtectionDomain().getCodeSource().getLocation().toString().endsWith("/classes/"),"native storage consumer is production");check(StorageProviders.class.getProtectionDomain().getCodeSource().getLocation().toString().endsWith("/classes/"),"provider facade is production");check(VisibleLootStorage.class.getProtectionDomain().getCodeSource().getLocation().toString().contains("provider-native-fixtures"),"consumer authority is explicitly authored, not an original provider");
  NativeStorage.clear();var square=new IsoGridSquare(12000,9000,0);var parent=new IsoObject();parent.square=square;parent.sprite=new zombie.iso.sprite.IsoSprite();square.objects.add(parent);var container=new ItemContainer();container.parent=parent;parent.container=container;var player=new zombie.characters.IsoPlayer();player.square=square;player.cell=new IsoCell();player.cell.square=square;zombie.characters.IsoPlayer.players[0]=player;
  var nativeBind=new viewpoint.packs.PackBind();nativeBind.model=new viewpoint.render.PackModel();parent.sprite.binding=nativeBind;PackedModelGeometry.store(nativeBind.model,StorageFrameTest.V,StorageFrameTest.OPEN,3);
  var actual=new viewpoint.packs.PackBind();actual.model=new viewpoint.render.PackModel();PackedModelGeometry.store(actual.model,StorageFrameTest.V,StorageFrameTest.OPEN,3);VisibleLootStorage.owner=parent;VisibleLootStorage.enabled=true;VisibleLootStorage.source=true;VisibleLootStorage.visible=false;VisibleLootStorage.housing=new ShelfBridge.Binding(actual,true,true,71,System.nanoTime());VisibleLootStorage.placement=new StorageProviders.Pose(12000.65f,9000.4f,.1f,0,1,.8f);
  var item=new InventoryItem(17);item.container=container;container.items.add(item);var platform=new J2SEPlatform();var row=platform.newTable();String[] keys={"v","id","slot","x","y","z","qx","qy","qz","qw","rev"};double[] values={1,17,0,.5,.5,.5,0,0,0,1,1};for(int n=0;n<keys.length;n++)row.rawset(keys[n],values[n]);row.rawset("key","provider-storage");row.rawset("auto",true);var rows=platform.newTable();rows.rawset(17d,row);NativeStorage.publish(container,"provider-storage",rows);
  SdkPins.shelves=false;VisibleLootStorage.enabled=false;NativeStorage.publish(container,"provider-storage",rows);check(field("selected")==null,"missing KK and VL Off cannot publish generic contents");VisibleLootStorage.enabled=true;VisibleLootStorage.owner=parent;VisibleLootStorage.housing=new ShelfBridge.Binding(actual,true,true,71,System.nanoTime());VisibleLootStorage.placement=new StorageProviders.Pose(12000.65f,9000.4f,.1f,0,1,.8f);NativeStorage.publish(container,"provider-storage",rows);check(field("selected")!=null,"recognized VL bootstrap works with KK absent");
  var hidden=frame();NativeStorage.capture(hidden);check(hidden.scene.models.count()==0&&NativeStorage.nearest(new ContactFrame.Point(12000.5,9000.5,.2),System.nanoTime())==null,"unadmitted source publishes neither duplicate native item nor contact");check(item.container==container&&container.items.size()==1&&item.world==null,"waiting cannot clone, transfer or remove real inventory");
  VisibleLootStorage.visible=true;for(int eye=0;eye<2;eye++){var f=frame();VisibleLootStorage.expected=f.scene;NativeStorage.capture(f);check(f.scene.models.count()==1&&f.scene.models.key(0)==item&&VisibleLootStorage.admitted==f.scene,"native original item follows exact current eye admission "+eye);}
  var fitted=(StorageFrame)field("fitted");check(Math.abs(fitted.origin().x()-12000.65)<.001&&Math.abs(fitted.origin().y()-9000.4)<.001&&Math.abs(fitted.origin().height()-.1)<.0001&&fitted.cos()==0&&fitted.sin()==1&&fitted.scale()==.8f,"native producer uses captured final housing pose rather than guessed base binding");check(field("fittedModel")==actual.model,"interior contacts/packing use actual selected housing CPU model");
  VisibleLootStorage.expected=new viewpoint.render.SceneData();var wrong=frame();NativeStorage.capture(wrong);check(wrong.scene.models.count()==0,"foreign or partial-eye admission cannot borrow previous native rows");
  VisibleLootStorage.expected=null;VisibleLootStorage.source=false;var retired=frame();NativeStorage.capture(retired);check(retired.scene.models.count()==0&&NativeStorage.nearest(new ContactFrame.Point(12000.5,9000.5,.2),System.nanoTime())==null,"provider retirement cancels previous visual and contact lease");
  check(item.container==container&&container.contains(item)&&container.items.size()==1&&item.world==null,"source failure preserves the same native inventory identity and quantity");NativeStorage.clear();check(field("selected")==null&&field("bodies")==null,"explicit storage close retires selection and physical bodies");
  System.out.println("Native provider consumer: "+checks+" checks passed");
 }
}
